-- Freshroots demand planning: one-paste setup for a new Supabase project.
-- Supabase dashboard > SQL Editor > New query > paste this file > Run.
-- Creates the tables and loads the seed data, the 3 demo SKUs, run 1 with Raghav's
-- decisions and its Zoho export, and the halted test run 2.
-- Generated from db/migrations/*.sql and the local database. Run it on an EMPTY project only.

begin;

-- ===== db/migrations/001_sap_data.sql =====
-- Step 1: tables that hold the SAP export (sales, stock, masters).
-- Loads are upserts, so re-loading the same export is safe.

create table if not exists distributors (
  distributor_id   text primary key,
  distributor_name text not null,
  region           text not null,
  status           text not null
);

create table if not exists skus (
  sku_id               text primary key,
  sku_name             text not null,
  category             text not null,
  perishability        text not null check (perishability in ('Low', 'High')),
  standard_reorder_qty integer not null check (standard_reorder_qty > 0),
  unit_of_measure      text not null,
  distributor_id       text not null references distributors (distributor_id),
  -- Not in the SAP export yet. When null, the extract shows the first week of sales instead.
  launch_date          date
);

create table if not exists weekly_sales (
  sku_id     text not null references skus (sku_id),
  iso_week   text not null,           -- as exported, e.g. 2026-W27
  week_start date not null,           -- Monday of that ISO week
  units_sold integer not null check (units_sold >= 0),
  primary key (sku_id, week_start)
);

create table if not exists inventory_snapshots (
  sku_id        text not null references skus (sku_id),
  location      text not null,
  as_of_date    date not null,
  units_on_hand integer not null check (units_on_hand >= 0),
  primary key (sku_id, location, as_of_date)
);

-- Optional file. If it is never loaded, stock on order counts as 0 and every run warns.
create table if not exists open_purchase_orders (
  po_number     text not null,
  sku_id        text not null references skus (sku_id),
  qty_on_order  integer not null check (qty_on_order >= 0),
  expected_date date,
  as_of_date    date not null,
  primary key (po_number, sku_id, as_of_date)
);

create table if not exists festival_calendar (
  year_month        text primary key,  -- e.g. 2026-10
  is_festival_month boolean not null
);

create table if not exists load_batches (
  id         bigserial primary key,
  loaded_at  timestamptz not null default now(),
  source_dir text not null,
  row_counts jsonb not null,
  rejected   jsonb not null default '[]'
);

-- ===== db/migrations/002_runs.sql =====
-- Steps 4-8: runs, recommendations, Raghav's decisions and Zoho exports.

create table if not exists runs (
  id                   bigserial primary key,
  run_date             date not null,
  trigger              text not null check (trigger in ('manual', 'schedule', 'cli')),
  triggered_by         text,
  started_at           timestamptz not null default now(),
  finished_at          timestamptz,
  status               text not null check (status in ('running', 'completed', 'halted', 'failed')),
  halt_reasons         jsonb not null default '[]',
  warnings             jsonb not null default '[]',
  error                text,
  sku_count            integer,
  flag_counts          jsonb,
  sales_rows_in_window integer,
  reasons_report       jsonb,
  load_batch_id        bigint references load_batches (id),
  extract_xlsx         bytea
);

create table if not exists recommendations (
  id               bigserial primary key,
  run_id           bigint not null references runs (id) on delete cascade,
  sku_id           text not null,
  sku_name         text not null,
  perishability    text not null,
  unit_of_measure  text not null,
  distributor_id   text not null,
  distributor_name text not null,
  flag             text not null,
  action           text not null,
  suggested_qty    integer,
  rule_fired       text not null,
  rule_trace       jsonb not null,
  also_flagged     jsonb not null,
  judgment_reasons jsonb not null,
  numbers          jsonb not null,
  reason           text not null,
  reason_source    text not null check (reason_source in ('llm', 'template')),
  -- Raghav's feedback on the reason text (feeds the AI kill criterion).
  reason_marked_wrong boolean not null default false,
  unique (run_id, sku_id)
);

-- Append-only: every click is kept. The latest row per recommendation is the decision.
create table if not exists decisions (
  id                bigserial primary key,
  recommendation_id bigint not null references recommendations (id) on delete cascade,
  decision          text not null check (decision in ('APPROVE', 'CHANGE_QTY', 'HOLD')),
  final_qty         integer check (final_qty >= 0),
  reason            text,
  decided_by        text not null,
  decided_at        timestamptz not null default now(),
  bulk              boolean not null default false,
  check (decision = 'APPROVE' or (reason is not null and length(trim(reason)) > 0))
);
create index if not exists decisions_by_rec on decisions (recommendation_id, id desc);

create table if not exists zoho_exports (
  id          bigserial primary key,
  run_id      bigint not null references runs (id) on delete cascade,
  created_at  timestamptz not null default now(),
  created_by  text not null,
  po_count    integer not null,
  line_count  integer not null,
  csv         text not null
);

-- Business kill criterion: finance enters actual losses per quarter.
create table if not exists pilot_outcomes (
  id                  bigserial primary key,
  period_label        text not null,
  stockout_loss_lakh  numeric not null check (stockout_loss_lakh >= 0),
  writeoff_loss_lakh  numeric not null check (writeoff_loss_lakh >= 0),
  entered_by          text not null,
  entered_at          timestamptz not null default now()
);

-- ===== db/migrations/003_row_level_security.sql =====
-- Supabase exposes every table in the public schema through its REST API using
-- the project's anon key. Turning on row-level security with no policies closes
-- that door. The app connects with the database connection string (table owner),
-- which RLS does not restrict, so the app is unaffected. Harmless on plain Postgres.

alter table distributors          enable row level security;
alter table skus                  enable row level security;
alter table weekly_sales          enable row level security;
alter table inventory_snapshots   enable row level security;
alter table open_purchase_orders  enable row level security;
alter table festival_calendar     enable row level security;
alter table load_batches          enable row level security;
alter table runs                  enable row level security;
alter table recommendations       enable row level security;
alter table decisions             enable row level security;
alter table zoho_exports          enable row level security;
alter table pilot_outcomes        enable row level security;

-- ===== data =====
2026-10-22,FR-20261022-R1-DIST001,NutriFlow Distributors,Demand run #1,Freshroots Mango Drink 200ml,SKU001,750,,Units,Draft,Approved as recommended
2026-10-22,FR-20261022-R1-DIST001,NutriFlow Distributors,Demand run #1,Freshroots Peanut Butter 300g,SKU013,120,,Units,Draft,Approved as recommended
2026-10-22,FR-20261022-R1-DIST002,GrainPath Logistics,Demand run #1,Freshroots Brown Rice 1kg,SKU003,300,,Units,Draft,Approved as recommended
2026-10-22,FR-20261022-R1-DIST002,GrainPath Logistics,Demand run #1,Freshroots Almond Milk 500ml,SKU004,300,,Units,Draft,Qty changed by Raghav: 150 only covers 1.5 weeks of festival demand
2026-10-22,FR-20261022-R1-DIST002,GrainPath Logistics,Demand run #1,Freshroots Millet Chips 60g (DEMO),SKU016,200,,Units,Draft,Qty changed by Raghav: New launch still ramping; one standard order
');
SELECT pg_catalog.setval('public.decisions_id_seq', 17, true);
SELECT pg_catalog.setval('public.load_batches_id_seq', 2, true);
SELECT pg_catalog.setval('public.pilot_outcomes_id_seq', 1, false);
SELECT pg_catalog.setval('public.recommendations_id_seq', 18, true);
SELECT pg_catalog.setval('public.runs_id_seq', 2, true);
SELECT pg_catalog.setval('public.zoho_exports_id_seq', 1, true);

commit;
